INSERT INTO pessoa_loja (loj_codigo, pes_codigo, loj_chave_server, loj_versao_server, loj_regime_federal, loj_crt, loj_porta, loj_ip, loj_matriz, loj_preco_aplicado, fig_codigo, ret_codigo, loj_sigla, loj_regime_municipal, loj_perfil, loj_atividade, cfnc_codigo_est_pag, cfnc_codigo_est_receb, cfnc_codigo_pagamentos, cfnc_codigo_recebimentos, cfnc_codigo_quebra, cfnc_codigo_sobra, loj_nome_exibicao)
VALUES (%(loj_codigo)s,
        (SELECT pes_codigo FROM pessoa WHERE pes_num_documento = %(pes_num_documento)s ORDER BY pes_codigo LIMIT 1),
        %(loj_chave_server)s, %(loj_versao_server)s, %(loj_regime_federal)s, %(loj_crt)s, %(loj_porta)s, %(loj_ip)s, %(loj_matriz)s, %(loj_preco_aplicado)s, %(fig_codigo)s, %(ret_codigo)s, %(loj_sigla)s, %(loj_regime_municipal)s, %(loj_perfil)s, %(loj_atividade)s, %(cfnc_codigo_est_pag)s, %(cfnc_codigo_est_receb)s, %(cfnc_codigo_pagamentos)s, %(cfnc_codigo_recebimentos)s, %(cfnc_codigo_quebra)s, %(cfnc_codigo_sobra)s, %(loj_nome_exibicao)s)
